usage.code:
// Nothing at all, for the common case: drag Buttons into Next Button and
// Previous Button and set Step Mode.

// A "3 / 7" readout needs no events — CurrentIndex tracks a drag live:
label.text = $"{snap.CurrentIndex + 1} / {snap.ItemCount}";

// Jumping straight to an item, e.g. from a menu:
snap.SnapTo(4);

// Switching how far a press travels at runtime:
snap.SetStepMode(ScrollSnapStep.Page);

// Dots that stay in sync, in one call:
paginationDots.BindToScrollSnap(snap);
